  let left = 1;
  for (let len = 1; len < 16; len++) {
    left = left * 2 - counts[len];
    if (left < 0) throw new ZipError("over-subscribed code");
  }
  if (max > 0 && left > 0 && (codeLengths || max !== 1)) throw new ZipError("incomplete code");
